import pkg from 'oxigraph';
import { readFileSync } from 'node:fs';
const { Store } = pkg;
const store = new Store();
store.load(readFileSync('/app/university_graph.ttl','utf8'), {format:'text/turtle', baseIRI:'http://university.org/ontology/'});
const file = process.argv[2];
const q = readFileSync(file,'utf8');
