PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?department (COUNT(DISTINCT ?student) AS ?n) WHERE {
  BIND("2025-08-16"^^xsd:date AS ?today)
  ?course uni:isTaughtIn ?department .
  ?student uni:isEnrolledIn ?course ; uni:hasEnrollmentDate ?enrolled .
  FILTER(?enrolled <= ?today)
  FILTER NOT EXISTS { ?student uni:hasGraduationDate ?g . FILTER(?g <= ?today) }
} GROUP BY ?department ORDER BY DESC(?n)
EOF
cd /tmp/sparql && node run.mjs /tmp/sparql/counts.rq && node run.mjs /app/solution.sparql

